//! 分支选择策略。

use std::collections::BTreeMap;

use crate::config::{ChoiceConfig, ChoiceDefault};

/// 离线导出时的分支选择器。
#[derive(Debug, Clone, Default)]
pub struct ChoicePolicy {
    default: ChoiceDefault,
    overrides: BTreeMap<String, usize>,
}

impl ChoicePolicy {
    /// 从配置构造.
    pub fn new(config: &ChoiceConfig) -> Self {
        Self {
            default: config.default,
            overrides: config.overrides.clone(),
        }
    }

    /// 选择下标; `default_choice` 来自 `choose -defaultChoice`.
    pub fn choose(
        &self,
        scene: &str,
        line: usize,
        option_count: usize,
        default_choice: Option<u8>,
    ) -> usize {
        if option_count == 0 {
            return 0;
        }
        let max = option_count - 1;
        if let Some(index) = self.overrides.get(&format!("{scene}:{line}")) {
            return (*index).min(max);
        }
        match self.default {
            ChoiceDefault::First => 0,
            ChoiceDefault::Last => max,
            ChoiceDefault::DefaultChoice => default_choice
                .map(usize::from)
                .filter(|index| *index <= max)
                .unwrap_or(0),
        }
    }

    /// 追加/覆盖一个分支选择 (行号从 0 开始).
    pub fn set_override(&mut self, scene: impl Into<String>, line: usize, index: usize) {
        self.overrides
            .insert(format!("{}:{line}", scene.into()), index);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn first_last_and_default_choice() {
        let mut config = ChoiceConfig::default();
        let policy = ChoicePolicy::new(&config);
        assert_eq!(policy.choose("start.txt", 1, 3, Some(2)), 0);

        config.default = ChoiceDefault::Last;
        let policy = ChoicePolicy::new(&config);
        assert_eq!(policy.choose("start.txt", 1, 3, Some(2)), 2);

        config.default = ChoiceDefault::DefaultChoice;
        let policy = ChoicePolicy::new(&config);
        assert_eq!(policy.choose("start.txt", 1, 3, Some(2)), 2);
        assert_eq!(policy.choose("start.txt", 1, 3, Some(9)), 0);
    }

    #[test]
    fn overrides_win_and_are_clamped() {
        let mut config = ChoiceConfig::default();
        config.overrides.insert("start.txt:7".to_owned(), 9);
        let policy = ChoicePolicy::new(&config);
        assert_eq!(policy.choose("start.txt", 7, 2, None), 1);
        assert_eq!(policy.choose("start.txt", 8, 2, None), 0);
    }
}
